 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05234.txb_ISUR_CD_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    00726 - 소속부유형코드
     */
    const arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "A^전체,";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // alert("vListMdCd :"+vListMdCd);
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        let pAFCHG_SECT_TP_CD = cmb_AFCHG_SECT_TP_CD.getValue();
        if (cmb_AFCHG_SECT_TP_CD.getValue() === "") {
            pAFCHG_SECT_TP_CD = "A";
        }
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&AFCHG_SECT_TP_CD=" + pAFCHG_SECT_TP_CD;
        url += "&PROCS_STAT_CD=" + rdo_PROCS_STAT_CD.getValue();
        url += "&DATE_TYP=" + rdo_DATE_TYP.getValue();
        url += "&SDATE=" + edt_SDATE.getValue();
        url += "&EDATE=" + edt_EDATE.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD !== '2') {
            await $c.win.alert("[소속부변경]업무는 코스닥회사만 해당합니다. 회사을 다시 선택바랍니다");
        }
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    const options = {
        id: "ULDSTF05235",
        title: "소속부변경관리",
        type: "browserPopup",
        width: "710px",
        height: "725px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05235.gfm", options);
};

/**
 * @method
 * @name openRecvDetail
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openRecvDetail = async function(row, colid) {
    scwin.setContnId(row);
    await $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
    /////////////////////
    await scwin.search();
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            scwin.gAcptNo = dts_List_1.getCellData(Number(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_1.getCellData(Number(obj), "FORM_CD");
            scwin.gFormVer = dts_List_1.getCellData(Number(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_1.getCellData(Number(obj), "ISUR_CD");
            scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

        } else {
            scwin.gBzProcsNo = dts_List_2.getCellData(Number(obj), "BZ_PROCS_NO");
            scwin.gAcptNo = dts_List_2.getCellData(Number(obj), "ACPT_NO");
            scwin.gListProcsStatCd = dts_List_2.getCellData(Number(obj), "LIST_PROCS_STAT_CD");
        }
        // alert("gBzProcsNo():"+gBzProcsNo);

        // alert("gAcptNo():"+gAcptNo);

        // alert("gListProcsStatCd():"+gListProcsStatCd);

    }
};
